    "description": "Write a Client Final / End-of-Engagement deck the way a tier-1 strategy engagement manager actually writes one — Pyramid Principle for the structure, SCQA for the opening, action-titled slides for everything in between, because the deck is the partner's reputation in the client's hands. A 20-slide, 1920×1080 reference deck for a 6-12 week strategy engagement final-readout, designed to be both presented and self-read. Three irreducible disciplines — a Governing Thought + Top-of-Pyramid on slide 02, action titles (full sentences, not topics) on every body slide, and an Implementation Roadmap with named owners on slide 18 that converts insight into work plans within 7 days. Reference structure grounded in Barbara Minto's Pyramid Principle, the SCQA opening, and Gene Zelazny's chart-choice discipline. Use for end-of-engagement readouts at the Partner-to-CXO level, board-level strategy syntheses, post-merger integration reviews, and pre-investment due-diligence final reports.",
