    "shortDescription": "Day 1 the client sees 12 weeks; every SteerCo after is green, yellow, or red.",
    "description": "Write a Kickoff / SteerCo / Monthly Progress deck the way a tier-1 strategy project manager actually writes one — Day 1 the client has to see the 12-week path; every SteerCo after that is a green / yellow / red dashboard, never a story. A 14-slide, 1920×1080 reference deck that is one deck reused three ways — Kickoff (week 0), SteerCo (every 2 weeks), Monthly Progress (every 4 weeks) — by swapping the appropriate cover sheet and dashboard variant. Three irreducible disciplines — a 12-week Gantt with workstreams + named owners on slide 03, a RAG (red-amber-green) dashboard on slide 04 with decisions-needed in red, and a Decisions Required Today slide near the close that lists 1-3 binary asks. Reference structure grounded in PMI's PMBOK Guide, top-tier consulting's results-delivery approach, and the SteerCo discipline codified across MBB. Use for client kickoff meetings, mid-engagement SteerCo updates, monthly progress reports to the sponsor, and the project-management chapters of an engagement workplan.",
