    "shortDescription": "Porter, SWOT, BMC, PESTEL, Ansoff — five frameworks, one consistent pack, three decisions.",
    "description": "Write a Classic Consulting Framework Pack the way a tier-1 strategy senior partner actually writes one — Porter / SWOT / Business Model Canvas / PESTEL / Ansoff in a single, structurally consistent pack so the client can pattern-match across frameworks instead of re-orienting every two slides. A 22-slide, 1920×1080 reference pack that operationalizes the five canonical strategy frameworks on one engagement, with a synthesis slide that converts framework outputs into 3 strategic moves. Three irreducible disciplines — one framework per chapter (no mixing), every framework slide ends with the same 'So What' callout style, and a Synthesis slide at slide 22 that explicitly translates framework outputs into named decisions, not 'further analysis'. Reference structure grounded in Porter (1979/1980), the SWOT origin literature, Osterwalder Business Model Canvas, PESTEL (Aguilar), and Ansoff (1957).",
