    "description": "Audit a quality issue the way a Big-4 IT-audit partner actually reports one — a 14-slide management-ready deck that puts findings, root cause, and remediation budget on slide 2, so the audit committee approves the fix before the meeting ends. Built against the IIA 2024 Global Internal Audit Standards (effective 9 January 2025) and the COSO 2013 Internal Control framework, with the IIA Three Lines Model wired into every recommendation. Three slot-locked disciplines — a top-5 findings inventory on slide 2 ranked by residual risk, a Findings Heatmap (5×5 Likelihood × Impact) on slide 3, and named first-line / second-line / third-line accountability on slide 10 — turn workpaper output into governance-grade reporting. Reference deck grounded in published Big-4 implementation guides (KPMG, Deloitte, EY, PwC) and PCAOB inspection findings. Use for quarterly audit committee reports, SOX deficiency briefings, ERM risk-appetite breaches, and post-incident root-cause reviews.",
