    "description": "Polish a draft deck to CEO-ready the way a tier-1 strategy Associate Partner actually polishes one at 11pm before a 6:30am read — a rewrite pass, not a from-scratch generator. A 6-pass HTML workflow that takes a 25-40 slide employee draft and returns a 10-16 slide CEO-ready deck in 1920×1080 with the pyramid inverted, every title rewritten as a complete-sentence takeaway, every chart stripped of chartjunk, and the deck cut to 60% of its input length. Three irreducible disciplines — Pyramid Inversion that auto-promotes the recommendation to slide ≤3 and demotes analysis to appendix, headline rewriting that linter-rejects nominal titles like \"Q3 Results\" in favour of complete-sentence takeaways, and a 6×6 bullet cap (≤6 bullets, ≤6 words per bullet) with chartjunk stripped to data-ink. Reference workflow grounded in Barbara Minto's Pyramid Principle, Garr Reynolds' Presentation Zen restraint, and Edward Tufte's data-ink ratio; for Chief-of-Staff pre-reads and exec-staff polish.",
