    "shortDescription": "All 1.0s? You sandbagged. Name the bet, own the miss.",
    "description": "Run a department OKR review the way a tier-1 exec staff actually runs one — score against the right rubric, name the next-quarter bet, own the misses. A 14-slide, 1920×1080 HTML reference deck for VPs and directors presenting quarterly to S-team or exec staff, where the failure modes are well-known: a 32-tile green/yellow/red dashboard with no story, or a victory-lap deck where every OKR scored 1.0 (which per the canon means the goals were sandbagged). Three irreducible disciplines — a Committed-vs-Aspirational Score Strip auto-flagging all-1.0 decks as likely sandbagged, a Next-Quarter Bet slide that linter-rejects \"keep executing\" and forces a named reallocation/hire/deprecation, and a Misses-with-Lessons slide where every missed OKR carries a named human owner plus a lesson. Grounded in John Doerr's *Measure What Matters*, Google re:Work's grading rubric, and the modern tier-1 exec-staff operating cadence.",
