    "description": "Stage a Capital Markets Day the way a public-company IR Head actually stages one — a 60-slide master deck that walks 200 sell-side analysts through your 3-5 year plan and moves the consensus model the following Monday. Built against SEC Regulation FD selective-disclosure rules, the IR Society / BNY Investor Day playbooks, and BlackRock's publicly-posted 2025 CMD as the current visual bar. Three slot-locked disciplines — equity story before any number (slides 3-10), a Long-Term Financial Algorithm chapter (slides 11-15) with vs-prior-CMD deltas, and a Prior-CMD Scorecard (slides 54-56) that shows what was promised vs delivered — turn the most expensive piece of IR communication of the year into a 2-week consensus-revision event. Reference deck grounded in BlackRock's 2025 Investor Day filings, the SEC Reg FD guidance, and the IR Impact 2024-2025 post-event measurement research. Use for triennial capital-markets days, refresh investor days, pre-IPO analyst days, and post-M&A long-term-target resets.",
