    "description": "Write an industry deep-dive deck the way a bulge-bracket Industry Group MD actually writes one — the 40-slide reference that gets pulled out for every banker pitch, every IPO marketing prep, and every PM deep-dive in the sector. A 20-slide, 1920×1080 reference deck running market sizing (TAM/SAM/SOM) × value-chain mapping × Porter's Five Forces × competitive landscape × winners-losers thesis — every claim traceable to a named source. Three irreducible disciplines — three-method TAM triangulation[^1], Porter's Five Forces[^2] applied to the actual industry economics (not generic bullets), and a bulge-bracket / tier-1-consulting-style winners-losers slide[^3] with thesis sentences for each named company. Reference deck grounded in a tech-sector deep-dive pattern but generalisable across consumer, healthcare, industrials. Use for sector kickoff decks, banker pitch books, investor education, M&A advisory pre-reads, and the \"we need an industry primer for the new analyst class\" moment.",
