    "description": "Apply an existing brand system to an existing deck the way a world-class design-studio partner actually does it — not \"swap the logo,\" but rebuild every slide so all seven brand systems (logo, typography, palette, grid, photography, charts, transitions) inherit a brand decision and the deck could only have come from this brand. Built for in-house brand managers, design leads, and marketing operations teams handed an off-brand sales pitch or all-hands deck three days before an external moment. Three irreducible disciplines — systemic application across all seven brand systems rather than cosmetic swap, an annotated Brand-Decision Map proving which decision drove which slide element, and a hard restraint of at most three type weights across the deck so the typography stays load-bearing.",
