    "shortDescription": "One idea per slide — cut copy by 60-80%, keep 50% of every slide empty.",
    "description": "Redesign an existing slide deck the way a world-class keynote design lead actually rebuilds one — delete to one idea per slide, one verb per slide, one image per slide, 50% negative space, one type family at two weights. Built for founders preparing for a launch event, marketing leads polishing an engineer-written deck before a CEO uses it externally, and in-house design teams asked to make a sales deck flagship-quality in 48 hours. Three irreducible disciplines — surgical word-count reduction (typically 60-80% per slide) rather than cosmetic reformatting, \"build, don't dump\" sequencing that turns one bullet-list slide into three slides with reveals, and a slide-by-slide diet tracker showing the cut so the surgery is auditable.",
