    "id": "data-viz-redesign-deck",
    "name": "Redo Data Viz like a Top Data-Visualization Designer",
    "slug": "data-viz-redesign-deck",
    "category": "design-craft",
    "shortDescription": "The chart is the wrong type, not the wrong color — encoding first, color last.",
    "description": "Redo the data viz in a deck the way a top data-visualization designer actually redoes it — pick the encoding first, declutter second, color last. A 12-slide, 1920×1080 chart-redesign deck for analysts, consultants, and BI leads whose monthly review decks ship 6-15 charts each. Three irreducible disciplines — every chart names the question it answers (charts without a question are deleted), every chart is placed on the Cleveland-McGill perceptual ladder before any palette decision, and small multiples share scale and color semantics (IBCS conformance). No 3D charts, no donuts where a bar works, no rainbow palettes, no dual y-axis without explicit cited reason. Use for monthly business reviews, board / CFO decks, BI portal templates, and any deck where readers say \"I couldn't read the chart.\"",
