    "shortDescription": "One specific feeling, named. Not \"we love you so much.\"",
    "description": "Write a Life-Event Storyboard deck the way a world-class animation storyboard artist actually writes one — for a wedding, a milestone birthday, a family memorial, a proposal, or a 50th-anniversary slideshow — by anchoring the deck to a single emotional spine (the one promise this person kept, the one room everyone returned to, the one decision that changed everything) and resisting the gravitational pull toward greeting-card sentimentality. A 16-slide, 1920×1080 reference deck a family member, best friend, or wedding emcee can fill in within an evening. Three irreducible disciplines — the Emotional Spine sentence on slide 02 (one feeling, named precisely), the Specificity-Over-Sentimentality rule on every story slide, and the Save-The-Pivot beat in the back half (one moment of contrast that earns the joy). Reference deck grounded in the world-class animation studio's published story rules[^1], the Joseph Campbell hero-arc taxonomy[^2], and Aaron Sorkin's \"intention + obstacle\" beat structure[^3].",
