    "shortDescription": "One feature. One ask. One room of 4-8 reviewers. Walk out with a yes.",
    "description": "Pitch a single feature investment the way a tier-1 tech PM actually writes an internal RFC — Problem × User Impact × Tradeoffs × Ask on four load-bearing slides, not a 25-slide PRD. A 12-slide reference deck for the 30-minute staff or VP review where one PM brings one feature and one ask to a room of 4-8 reviewers. Three irreducible disciplines — the Why-Now / Why-Us / Why-This triplet on slide 03, the populated Tradeoff Quadrant on slide 08 (this feature plus the rejected alternatives), and the Doshi Bar Raiser close on slide 11 (Decision / Recommendation / Tradeoffs / Risks). Grounded in Cagan's Inspired, Lenny Rachitsky's 1-Pager corpus, the Stripe RFC tradition documented in Will Larson's An Elegant Puzzle, and Shreyas Doshi's high-agency PM writing.",
