    "category": "product-management",
    "shortDescription": "Now / Next / Later — stop putting dates on Q4 you don't know yet.",
    "description": "Write a PRD and Product Roadmap deck the way a tier-1 SaaS Senior PM actually writes one — outcomes before features, problems before solutions, and a roadmap that ships Now / Next / Later instead of pretending to know what will be true in October. A 16-slide, 1920×1080 reference deck a Senior or Staff PM can fill in within 2 hours for a leadership review or cross-team kickoff. Three irreducible disciplines — the JTBD-style problem statement on slide 02 written as 'When … I want to … so I can …' before any solution is named, an Opportunity Solution Tree[^4] linking outcome → opportunity → solution → experiment on slide 06, and a Now / Next / Later roadmap[^1] on slide 10 with explicit confidence levels and zero date commitments past 'Now'. Reference structure grounded in Janna Bastow's Now/Next/Later roadmap[^1], Teresa Torres's Opportunity Solution Trees[^4], Marty Cagan's Inspired product-discovery principles[^3], and Anthony Ulwick's Jobs-to-be-Done canon[^5].",
    "language": "en-US",
