    "shortDescription": "It's not about being right — it's about persuading 7 people who are.",
    "description": "Write a Technical RFC deck the way a tier-1 tech Principal Engineer actually writes one — not to show what you built, but to persuade 7 peer reviewers who are each smarter than you in their own domain. A 16-slide, 1920×1080 reference deck a Senior Staff or Principal engineer can fill in within 3 hours for a cross-team design review. Three irreducible disciplines — an explicit Problem / Non-Goals split on slide 02 so reviewers cannot scope-creep the proposal, a Considered Alternatives matrix on slide 06 that names *why each was rejected* not just *what it was*, and an Open Questions slide that distinguishes between author-resolvable and reviewer-resolvable items. Reference structure grounded in the IETF RFC tradition[^1], the Joel Spolsky Painless Functional Spec model[^4], and the tier-1 tech design-doc culture documented by Riona MacNamara[^3] and the Pragmatic Engineer[^2]. Use for cross-team technical proposals, OSS RFC processes, internal platform-team RFCs, and Staff+ promotion artefact packs.",
