    "description": "Coach a retail client the way a top fiduciary financial advisor actually coaches one across the kitchen table — one decision, one form, one deadline, one phone number. An 8-slide, 1920×1080 reference deck a fee-only CFP, RIA, or insurance broker can fill in for one client meeting within 45 minutes. Three irreducible disciplines — a Reg-BI-compliant fiduciary disclosure on the cover, an Advisor's-Alpha attribution tag on the recommendation slide, and a tear-off Decision Card on the closing slide with exactly one action, one form, one deadline, one phone number. Reference deck grounded in the published *Advisor's Alpha* research, the CFP Board Code and Standards, SEC Regulation Best Interest, FINRA Rule 2210, and IRS Publications 590-A/B. Use for Roth-conversion conversations, RMD reminders, beneficiary reviews, tax-loss harvesting at year-end, open-enrollment 401(k) talks, and any client meeting where the deliverable is a signed action — not a market-outlook PDF.",
