    "shortDescription": "First diagram by minute 12 — and the student draws it themselves.",
    "description": "Lecture STEM engineering the way a top open-courseware course director actually lectures — a 36-slide, 80-90 minute deck where the first central diagram lands by minute 12, students draw it themselves, and the rest of the hour finally clicks. Built against Walter Lewin's 8.02 Physics II (still actively viewed two decades later), Erik Demaine / Jason Ku / Justin Solomon's 6.006 Introduction to Algorithms (Spring 2020), Eric Mazur's peer-instruction ConcepTest format (~2× normalised conceptual gain over traditional lecture), and Richard Mayer's Cognitive Theory of Multimedia Learning (12 design principles). Three slot-locked disciplines — the first Build-Up Diagram on slide 8-9 (by lecture minute 12), three to five ConcepTests across the 90 minutes (every 12-15 minutes per Mazur), and a Next-Lecture Hook on slide 34 that names one open question — turn a content-dump lecture into a self-directed-reading-between-sessions one.",
