    "shortDescription": "No claim without a citation — and the Monday 1:1 actually runs better.",
    "description": "Teach a manager-development workshop the way a top organizational-psychology professor actually runs one — every prescription cites the study, every module ends in a Monday-Morning-Move the trainee can execute by their next 1:1. A 12-slide, 1920×1080 reference module any corporate L&D lead or ExecEd faculty can fill in within 90 minutes. Three irreducible disciplines — an Evidence Card (source, year, N, effect size) on every prescription slide, one Monday-Morning-Move per module written as an observable behavior, and a published counter-example for intellectual honesty. Reference deck grounded in Edmondson's psychological-safety construct, Google's Project Aristotle, Grant's *Give and Take*, Goldsmith's feedforward, Klein's pre-mortem, and Buckingham–Goodall on weekly check-ins. Use for manager-cohort training, ExecEd modules, Chief-of-Staff leadership programs, ICF-coach workshops, and any \"soft-skills\" deck where the bar is whether next Tuesday's 1:1 actually runs better.",
