    "description": "Write a Sales Training deck the way a tier-1 SaaS Sales Enablement Director actually writes one — not a methodology recap, but verbatim talk tracks and objection-handling scripts a quota-carrying rep can read aloud on Monday's call. A 16-slide, 1920×1080 reference deck built around MEDDPICC qualification and the Sandler / Challenger objection-handling canon, shaped by Sales Enablement Society's certification body of knowledge so the deck delivers competency on a measurable ramp metric, not airtime. Three irreducible disciplines: a literal Discovery Call talk track with student fill-ins, an Objection Matrix that gives the rep exactly three responses to each of the top-7 objections, and a Role-play Certification slide where the rep is signed off by their manager before the deck is closed. Use for new-hire SDR bootcamps, mid-funnel AE upskilling, channel-partner enablement, and quarterly objection-refresh sessions after a product launch.",
