    "description": "Write a Wellness / Yoga / Mindfulness Workshop deck the way a top athleisure-brand studio master trainer actually writes one — not a curriculum overview, but every skill broken into a 10-minute block the consumer attendee can complete in their living room before the next slide. A 14-slide, 1920×1080 reference deck shaped by the ACE / NASM continuing-education standards and Mindful Schools' lesson architecture so a paying consumer leaves with one named ritual they will actually do tomorrow at 7 a.m. Three irreducible disciplines: every section is a 10-minute named block (warm-up, technique, cue, integration), every cue is verbalized with the literal coaching language the master trainer would say (not a description of the technique), and the closing slide is a printable Day-1 ritual card with a single chosen practice (not the whole curriculum). Use for in-studio member workshops, brand pop-up events, retail wellness floor sets, corporate wellness lunch-and-learns, and online live cohort intensives.",
