    "description": "Write an EHS Safety / Emergency-Drill Training deck the way an OSHA-authorized Outreach Trainer actually writes one — not a regulation tour, but anonymized real incidents from the same industry told in language a frontline worker reads in 30 seconds, then practices in a tabletop drill before lunch. A 16-slide, 1920×1080 reference deck shaped to OSHA 29 CFR 1910 / 1926, the NIOSH Hierarchy of Controls, and ISO 45001 OH&S so the deck satisfies recordable-training documentation while changing how a worker stops work. Three irreducible disciplines: every hazard slide opens with a real anonymized incident, every control is named on the Hierarchy of Controls ladder, and the closing slide is a Stop-Work Authority card with the worker's and supervisor's names printed on it. Use for new-hire orientation, annual OSHA refresh, post-incident retraining, contractor-onboarding gate, and emergency-drill walkthroughs.",
