    "shortDescription": "If they can't ship a first PR or first deck by Friday, your onboarding deck is decoration.",
    "description": "Write an Employee Onboarding deck the way a tier-1 enterprise L&D Senior Program Manager actually writes one — three modular tracks (Culture, Tools, Collaboration) wired to a 30-60-90 day plan, every slide ending with a concrete first-week action a new hire can take before lunch. An 18-slide, 1920×1080 reference deck built around the ATD 70-20-10 model and Kirkpatrick Levels 1-3 measurement so HRBPs and hiring managers can prove ramp-time improvement, not just say onboarding feels nicer. Three irreducible disciplines: a Culture track that names two operating principles and one tradeoff story per principle, a Tools track that includes a hands-on Day-1 setup checklist (not a screenshot tour), and a Collaboration track that scripts the new hire's first 1:1, first standup, and first Slack post. Use for the 90-minute Welcome session on Day 1, the self-serve LMS-hosted version, and the manager copy that ships with every hire.",
