    "shortDescription": "Seven formulas cover 80% of office work. Stop teaching the other 470.",
    "description": "Write an Excel Power-Skills Training deck the way a top certified Excel trainer actually writes one — not a function-by-function reference, but the seven formulas that cover roughly 80% of real office workflows, each taught with a literal dataset and a before/after table the learner reproduces in-session. A 14-slide, 1920×1080 reference deck shaped around the modern Excel canon (XLOOKUP, LET, dynamic arrays, Power Query) and Stephen Few's analytical-display principles. Three irreducible disciplines: the Seven-Formula Canon is the explicit spine of the deck, every formula is taught against a small real dataset (not a screenshot), and every formula slide ends with a 'break it on purpose' exercise that fixes the #N/A, #VALUE, and #SPILL errors learners actually hit. Use for in-company finance / ops / sales-ops upskilling, applied-analytics electives, and bootcamp data-skills modules.",
